   verificação prévia (preflight OPTIONS) que o Apps Script não responde. */
async function api(acao, dados){
  const resp = await fetch(API_URL, {
    method: 'POST',
    body: JSON.stringify(Object.assign({ acao, token: TOKEN }, dados || {}))
  });
  const json = await resp.json();
  if(!json.ok){
    const erro = new Error(json.erro || 'Falha na comunicação.');
    erro.resposta = json;                        // recusa por lotação vem com a contagem atual
    throw erro;
  }
  return json;
}

/* ------------------------------- lotação -------------------------------- */
/* A conferência que vale é a do servidor, dentro da trava. Aqui a página só
   reflete o resultado e evita que alguém insista num lugar que não existe. */
function capacidadeDoMural(lista){
  const ocupadas = (lista || []).reduce((s,r)=>s + (r.pessoas || 0), 0);
  return { limite:LIMITE_LUGARES, ocupadas, vagas:Math.max(0,LIMITE_LUGARES-ocupadas), esgotado:ocupadas >= LIMITE_LUGARES };
}

function normalizarCapacidade(c){
  if(!c || typeof c.ocupadas !== 'number') return null;
  const limite = typeof c.limite === 'number' && c.limite > 0 ? c.limite : LIMITE_LUGARES;
  const ocupadas = Math.max(0, c.ocupadas);
  return { limite, ocupadas, vagas:Math.max(0,limite-ocupadas), esgotado:ocupadas >= limite };
}

